        int acc;
        @BeforeEach void reset() { acc = 10; }
        @Test void adds() { acc += 5; check(acc == 15, "acc should be 15"); }
        @Test void freshStatePerTest() { check(acc == 10, "setup must run before each test"); }
        @Test void fails() { check(acc == 99, "expected 99"); }
